'use strict';
const reviewForm=document.querySelector('#reviewForm'),stateKey='task-author-stage4-v1';let connection=null,jobs=[],busy=false,poller=null;
const manual=['repeat','quality','cheat','numerics','sealed','timing','fair'];
function values(){const d={};for(const e of reviewForm.elements)if(e.name)d[e.name]=e.type==='checkbox'?e.checked:e.value;return d;}
function restore(d){if(!d||typeof d!=='object'||Array.isArray(d))throw Error('Invalid review notes');for(const e of reviewForm.elements)if(e.name){if(e.type==='checkbox')e.checked=d[e.name]===true;else e.value=typeof d[e.name]==='string'?d[e.name]:(e.name==='exceptionStatus'?'unresolved':'');}}
function exceptionReview(notes,task){
    const conflict=(notes.conflict||'').trim();
    const approved=!!conflict&&notes.exceptionStatus==='approved-sample'&&!!task&&task.endsWith('-sm')&&notes.exceptionTask===task;
    return {blocked:!!conflict&&!approved,approved,title:approved?'Sample-only exception approved — validation checks remain separate':conflict?'Rule conflict recorded — stop dependent work':'Validation evidence review'};
}
function save(){try{localStorage.setItem(stateKey,JSON.stringify({schema:'task-author.validation.v1',notes:values()}));document.querySelector('#saveState').textContent='Review notes saved locally.';}catch{document.querySelector('#saveState').textContent='Storage unavailable. Export evidence to preserve notes.';}document.querySelector('#summaryResult').hidden=true;}
function controls(){const active=jobs.some(j=>['queued','running'].includes(j.state)),ready=connection?.harbor&&connection?.dockerReady&&document.querySelector('#task').value&&document.querySelector('#reviewed').checked&&!active&&!busy;for(const id of ['oracle','nop','quality'])document.querySelector('#'+id).disabled=!ready||(id==='quality'&&!document.querySelector('#provider').checked);}
async function api(path,options={}){const r=await fetch(path,{cache:'no-store',...options});const d=await r.json();if(!r.ok)throw Error(d.issues?.length?d.error+'\n'+d.issues.join('\n'):d.error||'Runner request failed.');return d;}
async function refresh(){try{connection=await api('/api/status');document.querySelector('#runnerState').textContent=connection.harbor&&connection.dockerReady?'Runner connected · required tools available':'Runner connected · prerequisites missing';document.querySelector('#tools').textContent=`Harbor: ${connection.harbor?'available':'missing'} · Docker: ${connection.docker?'installed':'missing'} · Engine: ${connection.dockerReady?'ready':'unavailable'}. ${connection.dockerDetail}`;document.querySelector('#taskRoot').textContent=connection.taskRoot;const sel=document.querySelector('#task'),old=sel.value;sel.replaceChildren(new Option('Choose prepared task',''));for(const t of connection.tasks)sel.add(new Option(t,t));if(connection.tasks.includes(old))sel.value=old;await loadJobs();}catch{connection=null;document.querySelector('#runnerState').textContent='Local runner unavailable';document.querySelector('#tools').textContent='Start validation_server.py and open http://127.0.0.1:8765/dist/validation.html. Harbor and Docker must be installed separately.';}controls();}
function renderJobs(){const el=document.querySelector('#runs');el.replaceChildren();if(!jobs.length){const p=document.createElement('p');p.textContent='No execution records in this runner session. All checks remain unrun.';el.append(p);return;}for(const j of [...jobs].reverse()){const card=document.createElement('div');card.className='run';const title=document.createElement('h3');title.textContent=`${j.kind} · ${j.task} · ${j.state}`;card.append(title);const p=document.createElement('p');p.textContent=`Evidence: ${j.evidenceStatus} · Exit: ${j.exitCode??'pending'} · Harbor command elapsed: ${j.elapsedSeconds??'pending'} seconds`;card.append(p);const hash=document.createElement('p');hash.className='muted';hash.style.overflowWrap='anywhere';hash.textContent=`Fingerprint: ${j.fingerprint||'pending'} · Source unchanged at run end: ${j.sourceUnchanged===undefined?'not assessed':j.sourceUnchanged?'yes':'NO — rerun changed task'}`;card.append(hash);const detail=document.createElement('details'),sum=document.createElement('summary');sum.textContent='Run details and logs';detail.append(sum);const pre=document.createElement('pre');pre.textContent=JSON.stringify({id:j.id,startedAt:j.startedAt,command:j.command,rewards:j.rewards,ctrfReports:j.ctrfReports,error:j.error},null,2)+'\n\n'+(j.log||'No process log yet.');detail.append(pre);card.append(detail);el.append(card);}}
async function loadJobs(){if(!connection)return;try{jobs=await api('/api/jobs');renderJobs();controls();const active=jobs.some(j=>['queued','running'].includes(j.state));if(active&&!poller)poller=setInterval(loadJobs,3000);if(!active&&poller){clearInterval(poller);poller=null;}}catch{document.querySelector('#actionStatus').textContent='Could not refresh run evidence. Reconnect to the local runner.';}}
async function run(kind){busy=true;controls();document.querySelector('#actionStatus').textContent='Checking task structure and prerequisites…';try{await api('/api/run',{method:'POST',headers:{'Content-Type':'application/json','X-Task-Author':connection.token},body:JSON.stringify({task:document.querySelector('#task').value,kind,reviewed:document.querySelector('#reviewed').checked,providerConfirmed:document.querySelector('#provider').checked})});document.querySelector('#actionStatus').textContent='Check started. Logs and evidence will update below.';await loadJobs();}catch(e){document.querySelector('#actionStatus').textContent=e.message;}finally{busy=false;controls();}}
document.querySelector('#refresh').onclick=refresh;for(const id of ['oracle','nop','quality'])document.querySelector('#'+id).onclick=()=>run(id);for(const id of ['task','reviewed','provider'])document.querySelector('#'+id).onchange=controls;
reviewForm.addEventListener('input',save);reviewForm.addEventListener('change',save);
document.querySelector('#summary').onclick=()=>{save();const notes=values(),out=document.querySelector('#summaryResult');out.replaceChildren();const h=document.createElement('h2');const exception=exceptionReview(notes,document.querySelector('#task').value);h.textContent=exception.title;out.append(h);const items=[];const task=document.querySelector('#task').value,relevant=jobs.filter(j=>j.task===task);for(const kind of ['oracle','nop']){const observed=relevant.filter(j=>j.kind===kind&&j.evidenceStatus==='expected-reward-observed'&&j.sourceUnchanged);items.push(`${kind}: ${observed.length} run(s) with expected reward and a CTRF-shaped report; inspect fingerprints and repeats.`);}items.push(`Quality checks completed: ${relevant.filter(j=>j.kind==='quality'&&j.state==='completed').length}; human report review remains required.`);for(const name of manual)if(!notes[name])items.push('Manual evidence/declaration still needed: '+reviewForm.elements[name].parentElement.textContent.trim());if(exception.blocked)items.push('Discuss this conflict and obtain explicit user permission before a conflicting action. External acceptance rules remain in force.');if(exception.approved)items.push('User approval is recorded only for sample '+task+'. The documented exception does not establish external acceptance, approve another task, or mark any check passed.');items.push('The source difficulty-band contradiction remains unresolved. This page does not issue project approval or certify submission readiness.');const ul=document.createElement('ul');for(const item of items){const li=document.createElement('li');li.textContent=item;ul.append(li);}out.append(ul);out.hidden=false;out.scrollIntoView({behavior:'smooth'});};
document.querySelector('#export').onclick=async()=>{save();await loadJobs();const payload={schema:'task-author.validation.v1',exportedAt:new Date().toISOString(),notes:values(),runs:jobs,ruleStatus:{difficultyBand:'unresolved',externalApproval:'not-assessed'}};const u=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download='validation-evidence.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};
document.querySelector('#import').onclick=()=>document.querySelector('#file').click();document.querySelector('#file').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>5000000)throw Error('Evidence file exceeds 5 MB');const p=JSON.parse(await f.text());if(p.schema!=='task-author.validation.v1')throw Error('Unrecognized evidence record');restore(p.notes);save();document.querySelector('#saveState').textContent='Review notes imported. Imported run claims are not treated as runner-observed evidence.';}catch(err){document.querySelector('#saveState').textContent='Import failed: '+err.message;}e.target.value='';};
try{const old=JSON.parse(localStorage.getItem(stateKey)||'null');if(old?.schema==='task-author.validation.v1')restore(old.notes);}catch{}refresh();
